534		got, err := s.GetBatch("B1")
535		if err != nil || got.Status != StatusDraft {
536			t.Fatalf("重放不应改变批次: %v %+v", err, got)
537		}
538	
539		// 开始执行后重放创建请求，返回的仍是第一次成功时的草稿视图。
540		if _, err := s.StartBatch("s1", "B1"); err != nil {
541			t.Fatal(err)
542		}
543		b3, err := s.CreateBatch("b1", "B1", "R1", "v1", 10)
544		if err != nil {
545			t.Fatal(err)
546		}
547		if b3.Status != StatusDraft {
548			t.Fatalf("重放应返回第一次成功的结果（草稿），得到状态 %s", b3.Status)
549		}
550	
551		// 投料重放：即使批次已关闭，也返回原结果且不新增。
552		fixedTime := time.Date(2026, 3, 4, 8, 0, 0, 0, time.UTC)
553		if _, err := s.AddFeeding("f1", "B1", "M1", "100", fixedTime, "张三"); err != nil {
554			t.Fatal(err)
555		}
556		if _, err := s.CloseBatch("c1", "B1"); err != nil {
557			t.Fatal(err)
558		}
559		f2, err := s.AddFeeding("f1", "B1", "M1", "100", fixedTime, "张三")
560		if err != nil {
561			t.Fatalf("关闭后重放投料失败: %v", err)
562		}
563		if f2.Seq != 1 || f2.Grams != "100" {
564			t.Fatalf("重放投料结果不正确: %+v", f2)
565		}
566		got, _ = s.GetBatch("B1")
567		if len(got.Feedings) != 1 {
568			t.Fatalf("重放不应新增投料，得到 %d 条", len(got.Feedings))
569		}
570	}
